CREATE TABLE orders(id TEXT PRIMARY KEY,brand TEXT,product TEXT,amount INTEGER,customer_jid TEXT,status TEXT,transaction_id TEXT,created_at TEXT,verified_at TEXT); CREATE TABLE groups(id TEXT PRIMARY KEY,antilink INTEGER,antispam INTEGER); CREATE TABLE audit_logs(id INTEGER PRIMARY KEY,event TEXT,payload TEXT,created_at TEXT); CREATE INDEX idx_order_status ON orders(status); CREATE INDEX idx_order_brand ON orders(brand);
CREATE TABLE IF NOT EXISTS members(member_id TEXT PRIMARY KEY,status TEXT,name TEXT,whatsapp TEXT,gmail TEXT,instagram TEXT,tiktok TEXT,po_bussid TEXT,po_ets2 TEXT,affiliation TEXT,consent_version TEXT,consent_at TEXT,created_at TEXT);
CREATE TABLE IF NOT EXISTS private_documents(document_id TEXT PRIMARY KEY,member_id TEXT,type TEXT,storage_ref TEXT,sha256 TEXT,verification_status TEXT,verified_by TEXT,uploaded_at TEXT,retention_until TEXT);
CREATE TABLE IF NOT EXISTS purchases(purchase_id TEXT PRIMARY KEY,member_id TEXT,order_id TEXT,brand TEXT,product TEXT,kind TEXT,author TEXT,amount INTEGER,payment_status TEXT,evidence_ref TEXT,receipt_ref TEXT,created_at TEXT);
CREATE TABLE IF NOT EXISTS finance(transaction_id TEXT PRIMARY KEY,date TEXT,type TEXT,brand TEXT,category TEXT,description TEXT,amount INTEGER,method TEXT,order_id TEXT,member_id TEXT,status TEXT,evidence_ref TEXT);
CREATE TABLE IF NOT EXISTS media_reviews(review_id TEXT PRIMARY KEY,member_id TEXT,asset_ref TEXT,ai_indication TEXT,confidence REAL,human_review TEXT,final_status TEXT,reviewer TEXT,reviewed_at TEXT);
CREATE TABLE IF NOT EXISTS member_audit(id INTEGER PRIMARY KEY AUTOINCREMENT,timestamp TEXT,actor TEXT,action TEXT,member_id TEXT,result TEXT,reason TEXT);